def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row),
             key=lambda c: sum(row.count(c) for row in grid))

    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        if (ny, nx) not in seen and grid[ny][nx] == color:
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            comps.append((color, cells))

    fillers = [comp for comp in comps if len(comp[1]) <= 6]
    filler_area = sum(len(cells) for _, cells in fillers)

    chosen = None
    for color, cells in comps:
        if len(cells) <= 6:
            continue
        rs = [r for r, _ in cells]
        cs = [c for _, c in cells]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        holes = [(r, c) for r in range(r0, r1 + 1)
                 for c in range(c0, c1 + 1) if grid[r][c] == bg]
        if len(holes) == filler_area and holes:
            chosen = (color, r0, r1, c0, c1)
            break

    color, r0, r1, c0, c1 = chosen
    out = [[bg if grid[r][c] == bg else color
            for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]

    holes_seen = set()
    unused = list(fillers)
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if grid[r][c] != bg or (r, c) in holes_seen:
                continue
            stack = [(r, c)]
            holes_seen.add((r, c))
            region = []
            while stack:
                y, x = stack.pop()
                region.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if r0 <= ny <= r1 and c0 <= nx <= c1:
                        if grid[ny][nx] == bg and (ny, nx) not in holes_seen:
                            holes_seen.add((ny, nx))
                            stack.append((ny, nx))
            match = next((comp for comp in unused
                          if len(comp[1]) == len(region)), None)
            if match is None:
                match = unused[0]
            unused.remove(match)
            for y, x in region:
                out[y - r0][x - c0] = match[0]
    return out
